namespace App\Policies;

use App\Models\User;
use App\Models\ServerSnapshot;

class ServerSnapshotPolicy
{
    public function restore(User $user, ServerSnapshot $snapshot): bool
    {
        return $user->account_id === $snapshot->server->account_id
            && $user->can('manage-infrastructure');
    }
}
